(async function () {
  setTimeout(() => {
    var badge = document.querySelector("a[data-platform-badge]");
    if (!badge) {
      return;
    }
    badge.style.display = "none";

    // Fetch badge-config
    fetch("https://www.macaly.com" + '/api/badge-config?chatId=' + encodeURIComponent("sg5l47crcqitqgfocecivv1r"))
      .then(function (res) {
        return res.json();
      })
      .then(function (data) {
        // Set badge link and show badge
        if (badge) {
          badge.href = data.link;
          var isTextBadge = typeof data.content === "string" && !!data.content.trim();
          if (isTextBadge) {
            // The default SVG draws its own pill; custom text needs one on the anchor.
            badge.style.cssText += "align-items:center;justify-content:center;border-radius:999px;background:#000;color:#fff;padding:8px 12px;font-family:Arial,sans-serif;font-size:13px;font-weight:600;line-height:16px;max-width:calc(100vw - 20px);overflow:hidden;text-decoration:none;text-overflow:ellipsis;white-space:nowrap;box-shadow:0 8px 24px rgba(0,0,0,0.18);z-index:2147483647;";
            badge.textContent = data.content;
          }
          if (data.badgeVisibility) {
            badge.style.display = isTextBadge ? "inline-flex" : "block";
          }
        }
      });
  }, 200);
})();
